WITH store_total AS ( SELECT ss.ss_store_sk, SUM(ss.ss_net_profit) AS total_net_profit, SUM(ss.ss_quantity) AS total_quantity FROM store_sales ss GROUP BY ss.ss_store_sk ), store_gender AS ( SELECT ss.ss_store_sk, cd.cd_gender, SUM(ss.ss_net_profit) AS gender_net_profit, SUM(ss.ss_quantity) AS gender_quantity FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk GROUP BY ss.ss_store_sk, cd.cd_gender ), store_customer AS ( SELECT ss.ss_store_sk, AVG(c.c_birth_year) AS avg_birth_year FROM store_sales ss JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk GROUP BY ss.ss_store_sk ) SELECT sg.ss_store_sk, sg.cd_gender, sg.gender_net_profit, sg.gender_quantity, sg.gender_net_profit / SUM(sg.gender_net_profit) OVER (PARTITION BY sg.ss_store_sk) AS net_profit_pct_of_store, sg.gender_quantity / SUM(sg.gender_quantity) OVER (PARTITION BY sg.ss_store_sk) AS quantity_pct_of_store, st.total_net_profit, st.total_quantity, RANK() OVER (ORDER BY st.total_net_profit DESC) AS store_profit_rank, sc.avg_birth_year, CASE WHEN sg.gender_net_profit > (SELECT AVG(gender_net_profit) FROM store_gender WHERE ss_store_sk = sg.ss_store_sk) THEN 'Above Avg' ELSE 'Below Avg' END AS gender_perf_flag FROM store_gender sg JOIN store_total st ON st.ss_store_sk = sg.ss_store_sk JOIN store_customer sc ON sc.ss_store_sk = sg.ss_store_sk ORDER BY store_profit_rank, sg.ss_store_sk, sg.cd_gender
